    };
    internal static string Text(string key) => Text(key, UiLanguage.Current);
    internal static string Text(string key, ApplicationLanguage language)
    {
        if (!Values.TryGetValue(key, out var values)) return AiConnectionText.Text(key, language);
        int index = language switch { ApplicationLanguage.SimplifiedChinese => 0, ApplicationLanguage.TraditionalChinese => 1, ApplicationLanguage.English => 2, ApplicationLanguage.Japanese => 3, ApplicationLanguage.Korean => 4, ApplicationLanguage.Spanish => 5, ApplicationLanguage.French => 6, ApplicationLanguage.German => 7, ApplicationLanguage.Russian => 8, _ => 2 };
        return values[index];
    }
